Award [5 max]
Inputs – units used and days in month;
// do not allow a reference to a 2D array for the first marking point
Calculation of bill;
Calculation of units used per day;
Calculation of tax;
// allow references to a 2D array for calculations
Outputs – bill and units used per day;
Appropriate messages in inputs and outputs;
Example algorithm
UNITCOST = 0.2
DAILYCHARGE = 0.75
TAX = 0.1
input "units used this month? ", UNITMONTH
input "Days in month? ", DAYSINMONTH
BILL = (UNITCOST * UNITMONTH + DAILYCHARGE * DAYSINMONTH)
TOTALBILL = BILL + BILL * TAX
UNITDAY = UNITMONTH / DAYSINMONTH
output "The bill for this month is ", TOTALBILL
output "The number of units used per day were ", UNITDAY

